<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['counter_staff','handling_staff','supervisor','system_admin']);$pdo=$db->getConnection();$stmt=$pdo->query("SELECT COUNT(*) total,SUM(status='checked_in') checked_in,SUM(status='delayed') delayed,SUM(status='lost') lost FROM baggage");$s=$stmt->fetch()?:[];$recent=$pdo->query("SELECT b.baggage_code,b.status,b.weight,u.full_name,f.flight_number FROM baggage b JOIN users u ON b.passenger_id=u.id JOIN flights f ON b.flight_id=f.id ORDER BY b.created_at DESC LIMIT 10")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff Dashboard</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><span class="navbar-brand">Staff Dashboard</span><a class="text-white" href="../includes/logout.php">Logout</a></div></nav><div class="container py-4"><div class="row g-3 mb-4"><?php foreach(['Total'=>'total','Checked in'=>'checked_in','Delayed'=>'delayed','Lost'=>'lost'] as $label=>$key):?><div class="col-md-3"><div class="card"><div class="card-body"><div class="text-muted"><?=$label?></div><div class="fs-2"><?=intval($s[$key]??0)?></div></div></div></div><?php endforeach;?></div><div class="mb-3"><a class="btn btn-primary" href="baggage_register.php">Register baggage</a> <a class="btn btn-outline-primary" href="baggage_search.php">Search</a> <a class="btn btn-outline-secondary" href="tracking_update_simple.php">Tracking</a> <a class="btn btn-outline-secondary" href="reports.php">Reports</a></div><div class="card"><div class="card-header">Recent baggage</div><table class="table mb-0"><thead><tr><th>Code</th><th>Passenger</th><th>Flight</th><th>Status</th><th>Weight</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=htmlspecialchars($r['baggage_code'])?></td><td><?=htmlspecialchars($r['full_name'])?></td><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><?=htmlspecialchars($r['weight'])?></td></tr><?php endforeach;?></tbody></table></div></div></body></html>